python3 -B - <<'PY'
import json,subprocess,sys
chat=-1003847210571
registered={49:1436,104:1496,621:1675,990:1673,991:1671,992:1668,993:1666,994:1664,995:1662,996:1683,997:1681,998:1679,999:1677}
targets={tid:[mid] for tid,mid in registered.items()}
targets[104].append(1430)
ids=",".join(map(str,registered))
mids=",".join(str(mid) for values in targets.values() for mid in values)
def db(sql):
 p=subprocess.run(["docker","exec","-i","deploy-postgres-1","sh","-c",'exec psql -X -q -U "$POSTGRES_USER" -d gaybbs -At -F "|" -v ON_ERROR_STOP=1 -f -'],input=sql,text=True,capture_output=True,timeout=25)
 if p.returncode: raise RuntimeError("DB_QUERY_FAILED")
 return p.stdout.strip().splitlines()
rows=db(f"SELECT message_thread_id,message_id,state,pinned FROM topic_dm_entry_pins WHERE chat_id={chat} AND message_thread_id IN ({ids}) ORDER BY message_thread_id;")
expected=[f"{tid}|{registered[tid]}|published|t" for tid in sorted(registered)]
if rows!=expected: raise RuntimeError("ENTRY_LEDGER_CHANGED")
protected=db(f"SELECT COUNT(*) FROM topic_board_posts WHERE chat_id={chat} AND message_id IN ({mids}); SELECT COUNT(*) FROM board_menu_panels WHERE chat_id={chat} AND message_id IN ({mids});")
if protected!=["0","0"]: raise RuntimeError("NAVIGATION_PANEL_PROTECTED")
node=r"""
const fs=require("node:fs"),https=require("node:https");
const task=__TASK__;
const token=fs.readFileSync(process.env.BOT_TOKEN_FILE||"/run/secrets/bot_token","utf8").trim();
function api(method,data){
 return new Promise((resolve,reject)=>{
  const body=JSON.stringify(data);
  const req=https.request({hostname:"api.telegram.org",port:443,path:"/bot"+token+"/"+method,method:"POST",family:4,agent:false,headers:{"Content-Type":"application/json","Content-Length":Buffer.byteLength(body)}},res=>{
   let s="";res.setEncoding("utf8");res.on("data",x=>{if(s.length<200000)s+=x;});res.on("end",()=>{try{resolve(JSON.parse(s));}catch{reject(Error("API_RESPONSE_INVALID"));}});
  });
  const timer=setTimeout(()=>req.destroy(Error("TIMEOUT")),20000);
  req.on("close",()=>clearTimeout(timer));
  req.on("error",reject);req.end(body);
 });
}
(async()=>{
 const me=await api("getMe",{});
 if(!me.ok||String(me.result.username).toLowerCase()!=="gaybbs_bot"||me.result.id===8086265383)throw Error("BOT_IDENTITY_INVALID");
 if(task.chat!==-1003847210571||!Number.isSafeInteger(task.mid)||task.mid<1)throw Error("TARGET_INVALID");
 const result=await api("editMessageReplyMarkup",{chat_id:task.chat,message_id:task.mid,reply_markup:{inline_keyboard:[]}});
 if(!result.ok){console.log(JSON.stringify({status:"DENIED",code:result.error_code}));process.exitCode=2;return;}
 const m=result.result;
 if(!m||m.message_id!==task.mid||m.chat?.id!==task.chat||m.from?.id!==me.result.id||m.message_thread_id!==task.tid||m.reply_markup?.inline_keyboard?.length)throw Error("EDIT_READBACK_MISMATCH");
 console.log(JSON.stringify({status:"REMOVED",mid:m.message_id}));
})().catch(()=>{console.log(JSON.stringify({status:"UNCERTAIN"}));process.exitCode=3;});
"""
sample=node.replace("__TASK__",json.dumps({"chat":chat,"tid":49,"mid":1436}))
check=subprocess.run(["docker","exec","-i","deploy-gaybbs-1","node","--check","-"],input=sample,text=True,capture_output=True,timeout=15)
if check.returncode: raise RuntimeError("NODE_SYNTAX_FAILED")
def audit(tid):
 p=subprocess.run([sys.executable,"-B","scripts/userbot_topic_audit_client.py","--chat-id",str(chat),"--topic-id",str(tid)],text=True,capture_output=True,timeout=100)
 if p.returncode: raise RuntimeError("USERBOT_AUDIT_FAILED")
 data=[json.loads(x.split("=",1)[1]) for x in p.stdout.splitlines() if x.startswith("USERBOT_TOPIC_AUDIT=")]
 if len(data)!=1 or data[0].get("chat")!="area":raise RuntimeError("AUDIT_RESULT_INVALID")
 rows=[r for r in data[0]["rows"] if r["topic_id"]==tid]
 if len(rows)!=1:raise RuntimeError("TOPIC_ID_MISMATCH")
 return rows[0]
# Verify exact message identity against current Telegram history immediately before each edit.
failed=[]
for tid,values in targets.items():
 try:
  r=audit(tid)
  found=set(r.get("history_message_ids",[])+r.get("pin_message_ids",[]))
  if r.get("button_types")!=["normal"] or found!=set(values) or r.get("pin_state")!="ABSENT_FROM_PINS":
   raise RuntimeError("LIVE_TARGET_CHANGED")
  for mid in values:
   p=subprocess.run(["docker","exec","-i","deploy-gaybbs-1","node","-"],input=node.replace("__TASK__",json.dumps({"chat":chat,"tid":tid,"mid":mid})),text=True,capture_output=True,timeout=30)
   result=json.loads(p.stdout.strip())
   if p.returncode or result!={"status":"REMOVED","mid":mid}:
    raise RuntimeError("EDIT_NOT_CONFIRMED")
   if mid==registered[tid]:
    updated=db(f"UPDATE topic_dm_entry_pins SET pinned=FALSE,updated_at=NOW() WHERE chat_id={chat} AND message_thread_id={tid} AND message_id={mid} AND state='published' AND pinned=TRUE RETURNING message_id;")
    if updated!=[str(mid)]:raise RuntimeError("LEDGER_UPDATE_MISMATCH")
   print(f"AREA_POST_BUTTON_REMOVED={tid}:{mid}",flush=True)
 except Exception as exc:
  failed.append(tid)
  print(f"AREA_POST_BUTTON_UNCONFIRMED={tid}:{type(exc).__name__}:{str(exc) if isinstance(exc,RuntimeError) else 'CHECK_FAILED'}",flush=True)
print("AREA_REMOVE_FAILED_TOPICS="+",".join(map(str,failed)),flush=True)
if failed:raise SystemExit(1)
